from pathlib import Path
from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self): super().__init__(); self.ids=set(); self.hrefs=[]; self.scripts=[]; self.css=[]
    def handle_starttag(self, tag, attrs):
        d=dict(attrs)
        if 'id' in d: self.ids.add(d['id'])
        if tag=='a' and 'href' in d: self.hrefs.append(d['href'])
        if tag=='script' and 'src' in d: self.scripts.append(d['src'])
        if tag=='link' and d.get('rel')=='stylesheet': self.css.append(d.get('href'))
root=Path('/app/output')
for f in sorted(root.glob('*.html')):
    p=P(); p.feed(f.read_text())
    missing=[]
    for href in p.hrefs:
        if href.startswith('#') and href!='#' and href[1:] not in p.ids: missing.append(href)
        elif '.html#' in href:
            file,anchor=href.split('#',1)
            target=root/file
            if target.exists():
                q=P(); q.feed(target.read_text())
                if anchor not in q.ids: missing.append(href)
    assets=[a for a in p.scripts+p.css if not (root/a).exists()]
    print(f.name, 'anchors OK' if not missing else 'missing anchors '+str(missing), 'assets OK' if not assets else 'missing assets '+str(assets))
